def minPath(grid, k):
    N = len(grid)
    visited = [[False]*N for _ in range(N)]
    path = []
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def dfs(x, y, k):
        if k == 0:
            return True
        visited[x][y] = True
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and not visited[nx][ny] and grid[nx][ny] < grid[x][y]:
                if dfs(nx, ny, k - 1):
                    return True
        visited[x][y] = False
        return False

    for i in range(N):
        for j in range(N):
            if dfs(i, j, k - 1):
                path.append(grid[i][j])
                return sorted(path)
