def max_sub_array_sum_repeated(arr, n, k):
    # Calculate the maximum subarray sum for the original array
    def max_sub_array_sum(arr, n):
        max_so_far = arr[0]
        max_ending_here = arr[0]
        for i in range(1, n):
            max_ending_here = max(arr[i], max_ending_here + arr[i])
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    # If k is 1, the problem reduces to finding the maximum subarray sum of the original array
    if k == 1:
        return max_sub_array_sum(arr, n)

    # Calculate the maximum subarray sum for the repeated array
    total_sum = sum(arr)
    max_sum_k_times = max_sub_array_sum(arr, n) * k

    # If the total sum is negative, the maximum sum of any subarray will be less than or equal to the maximum subarray sum of the original array
    if total_sum < 0:
        return max_sub_array_sum(arr, n)

    # Calculate the maximum subarray sum considering the wrap-around case
    max_wrap_around_sum = max_sum_k_times - min_sub_array_sum(arr, n) * (k - 1)

    # Return the maximum of the two sums
    return max(max_sum_k_times, max_wrap_around_sum)

