def find_minimum_range(arrays):
    min_val = float('inf')
    max_val = float('-inf')

    # Find the minimum and maximum values across all arrays
    for arr in arrays:
        min_val = min(min_val, min(arr))
        max_val = max(max_val, max(arr))

    # Initialize variables to track the current range and the minimum range found
    current_min = float('inf')
    current_max = float('-inf')
    min_range = float('inf')

    # Iterate through the arrays to find the smallest range
    for i in range(min_val, max_val + 1):
        count = 0
        for arr in arrays:
            if i in arr:
                count += 1
        if count == len(arrays):
            current_min = i
            current_max = i
            break
        elif count > 0:
            current_min = min(current_min, i)
            current_max = max(current_max, i)
            if current_max - current_min < min_range:
                min_range = current_max - current_min

    return (current_min, current_max)

