def rearrange_bigger(n):
    # Convert the number to a list of its digits
    digits = list(str(n))

    # Traverse the list from right to left to find the first digit that is smaller than the digit immediately after it
    for i in range(len(digits) - 2, -1, -1):
        if digits[i] < digits[i + 1]:
            # Find the smallest digit on the right side of the found digit that is larger than it
            for j in range(len(digits) - 1, i, -1):
                if digits[j] > digits[i]:
                    # Swap the found digits
                    digits[i], digits[j] = digits[j], digits[i]
                    # Sort the digits to the right of the swapped position in ascending order
                    digits[i + 1:] = sorted(digits[i + 1:])
                    # Convert the list back to an integer and return it
                    return int(''.join(digits))
    # If no such pair is found, return False
    return False
