def largest_subset(arr, n):
    # Initialize the dp array where dp[i] will store the size of the largest divisible subset ending at index i
    dp = [1] * n

    # Iterate through each element in the array
    for i in range(1, n):
        # Check all previous elements to see if they can form a divisible subset with the current element
        for j in range(i):
            if arr[i] % arr[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    # The length of the largest divisible subset is the maximum value in the dp array
    return max(dp)

