```python
def coin_change(coins, m, n):
    # Create a table to store results of subproblems
    dp = [0] * (n + 1)

    # Initialize the table
    for i in range(n + 1):
        dp[i] = float('inf')

    # Base case
    dp[0] = 0

    # Fill the table in bottom-up manner
    for i in range(1, n + 1):
        for coin in coins:
            if coin <= i:
                sub_problem = dp[i - coin]
                if sub_problem != float('inf') and sub_problem + 1 < dp[i]:
                    dp[i] = sub_problem + 1

    # Return the minimum number of coins required
    return dp[n]

