def subset(arr, n):
    sum = 0
    for i in range(n):
        sum += arr[i]
    if sum % 2 != 0:
        return 0
    else:
        subset_sum = sum // 2
        dp = [0 for _ in range(subset_sum + 1)]
        dp[0] = 1
        for i in range(n):
            for j in range(subset_sum, arr[i] - 1, -1):
                dp[j] = dp[j] or dp[j - arr[i]]
        return dp[subset_sum]

